update public.learning_paths
set
  title = 'Printmaking',
  goal = 'Printmaking',
  summary = 'Students build safe, professional habits for shared print studios, tools, chemicals, presses, and cleanup, and translate visual ideas into printable matrices through reversal, mark, contrast, and sequence planning. They practice relief, intaglio, lithography, screenprinting, monotype, and hybrid processes; choose paper, ink, and color; control registration and editions; study printmaking as art, communication, reproduction, protest, commerce, and public circulation; and prepare finished prints through critique, contemporary multiples, exhibition, and archiving.',
  data = $prinjson${"slug": "printmaking", "title": "Printmaking", "description": "Students build safe, professional habits for shared print studios, tools, chemicals, presses, and cleanup, and translate visual ideas into printable matrices through reversal, mark, contrast, and sequence planning. They practice relief, intaglio, lithography, screenprinting, monotype, and hybrid processes; choose paper, ink, and color; control registration and editions; study printmaking as art, communication, reproduction, protest, commerce, and public circulation; and prepare finished prints through critique, contemporary multiples, exhibition, and archiving.", "topics": [{"id": "e167f5eb-83a0-4754-aa97-a322101407bb", "type": "topic", "title": "Printmaking Orientation, Studio Safety, and Shop Protocols", "description": "This opening section establishes the habits that make print studios safe and productive. Students learn that printmaking is physical, procedural, collaborative, and deeply dependent on cleanup, shared equipment, and process discipline.", "children": [{"id": "8f5f9064-8683-4dd0-a8d4-59b3148ce2a6", "type": "subtopic", "title": "Studio safety and personal protection", "children": [{"id": "a97aa26e-b36e-44ee-9706-41999fcc28ad", "type": "concept", "title": "Specific terms and topics:"}, {"id": "e438f27d-d3b9-45ca-be72-d6ac392818a2", "type": "concept", "title": "PPE"}, {"id": "0fe072c0-6b93-44b6-8505-077f552b99d1", "type": "concept", "title": "gloves"}, {"id": "f36123a6-9482-45bd-9cb9-6a4f7ac1b52e", "type": "concept", "title": "apron"}, {"id": "315bc246-fc05-4132-9f2f-ce78a2c0ac5d", "type": "concept", "title": "eye protection"}, {"id": "a59e7693-e270-4a91-82ff-1c08ef220be0", "type": "concept", "title": "ventilation"}, {"id": "9d334491-7273-45c7-9cda-b81a1e428907", "type": "concept", "title": "SDS sheet"}, {"id": "cea42164-7da7-4530-a643-712b0864f617", "type": "concept", "title": "solvent safety"}, {"id": "7bf8d77a-7f0c-4c18-895d-435aa15dd205", "type": "concept", "title": "