concept", "title": "rag disposal"}, {"id": "0961f5c0-c411-4fc7-8f48-5314b9c1ed8b", "type": "concept", "title": "screen washout"}, {"id": "3c47242d-d6a7-4cb1-9b82-0c812b638a1f", "type": "concept", "title": "plate cleaning"}, {"id": "15216969-29c0-4495-a810-e7139e80da1d", "type": "concept", "title": "tool checkout"}, {"id": "96b03b85-a707-4360-82dd-631c81d106e3", "type": "concept", "title": "drying rack"}, {"id": "9fd0915f-c309-4ab8-8c6d-4f5571c4e493", "type": "concept", "title": "labeling"}, {"id": "39edd342-bcc9-4293-840a-38d62dcce69c", "type": "concept", "title": "waste stream"}, {"id": "3e7b71a8-6a0a-4e7d-b4b7-270bc7c6e179", "type": "concept", "title": "reset protocol"}], "description": "Students learn that good studio citizenship is part of professional print practice."}]}, {"id": "0c6dc0f3-0cf3-4cf6-bd71-2e45433ce502", "type": "topic", "title": "Image Development, Drawing for Print, and Matrix Planning", "description": "Prints begin long before ink reaches paper. This section helps students design images for reversal, layers, line quality, tonal range, and the particular logic of the chosen matrix.", "children": [{"id": "c7e87ab8-a135-4fa1-842c-b47253c91f35", "type": "subtopic", "title": "Drawing for print", "children": [{"id": "503c3265-9a0e-4a44-8a79-64de2bf1f25a", "type": "concept", "title": "Specific terms and topics:"}, {"id": "1375030b-7a82-4a21-a8ee-a7818af293af", "type": "concept", "title": "thumbnail"}, {"id": "37766997-081e-4e82-be3b-809e4e95758f", "type": "concept", "title": "value study"}, {"id": "9fcfb9cd-b759-4661-a1f5-2379b1af9f69", "type": "concept", "title": "positive shape"}, {"id": "ff46a2f2-d137-4284-8ba5-d46c3d594f26", "type": "concept", "title": "negative space"}, {"id": "4310e705-59b4-4404-abec-5762a35d9b7a", "type": "concept", "title": "line weight"}, {"id": "f189c06e-8bb1-4813-95c9-4d7f956aa4d0", "type": "concept", "title": "hatching"}, {"id": "0a29b00e-6379-4850-8554-ffbc17157670", "type": "concept", "title": "cross-hatching"}, {"id": "