"}, {"id": "a54d321e-ac85-4779-8989-28fb8eb06638", "type": "concept", "title": "variation"}, {"id": "247cdaa8-32cf-4a15-8bd1-6cc3bee5efec", "type": "concept", "title": "repetition"}, {"id": "9adcc3bc-7942-45b1-9409-96ee9cf089ea", "type": "concept", "title": "appropriation"}, {"id": "5090abb4-5a26-4da0-9473-6fd1b38b8166", "type": "concept", "title": "index"}, {"id": "7221daf1-97ba-4d72-8893-85741449156d", "type": "concept", "title": "trace"}, {"id": "a654a48e-9637-40ca-823e-3c24abcf7c24", "type": "concept", "title": "material meaning"}, {"id": "944f3db3-0908-473a-b36e-c5435b94b08b", "type": "concept", "title": "process metaphor"}, {"id": "89e81cf1-8ca3-4c19-892f-40190556fff8", "type": "concept", "title": "audience"}], "description": "The goal is to choose a method because it serves the idea, not because it is merely available."}]}, {"id": "86ee354c-ebc5-4dad-a099-d45601e9cc59", "type": "topic", "title": "Relief Printing: Woodcut, Linocut, and Reduction Methods", "description": "Relief printing teaches direct mark-making, bold design, and the relationship between carved absence and printed presence. Students learn to carve safely and print consistently.", "children": [{"id": "264d4875-a24c-4949-a69a-50b887f35031", "type": "subtopic", "title": "Blocks and carving", "children": [{"id": "4482bc63-ba48-485e-ae0f-e02f1e8414a3", "type": "concept", "title": "Specific terms and topics:"}, {"id": "74f5c534-0855-4f0c-a6b3-4966863e2e9c", "type": "concept", "title": "woodcut"}, {"id": "67b60731-16d6-4255-b477-f29c1b7502b1", "type": "concept", "title": "linocut"}, {"id": "d6c3d9aa-331e-4045-b7f7-c8b6fe5d2ab5", "type": "concept", "title": "shina plywood"}, {"id": "fd5a502a-1ab2-4d75-b55f-f8a261aae5a7", "type": "concept", "title": "MDF block"}, {"id": "aa114f46-86a5-4abf-a651-957e2177fc11", "type": "concept", "title": "grain"}, {"id": "cda9aeb6-4e35-4c48-87c1-74f220f27366", "type": "concept", "title": "gouge"}, {"id": "61dc27d6-1f96-4785-b647-5b1d0724ce7d", "type": "concept", "title": "V-tool"}, {"id": "49ecb2fb-91f3-4784-8324-028caf2784c7", "type": "concept", "title": "U-gouge"}, {"id": "b0ab7e7e-3f29-4232-8374-c0cb0457cf63", "type": "concept", "title": "clearing"}, {"id": "184d96b1-7044-41e3-9e6f-1ff5aa043706", "type": "concept", "title": "chatter mark"}], "description": "Students develop control over tools, grain, surfaces, and carving direction."}, {"id": "a485af8e-602e-4bd9-a2e5-ed1bbfbeb32c", "type": "subtopic", "title": "Inking and printing", "children": [{"id": "abcadff6-1980-4e82-ae8e-d66bd58cd9ac", "type": "concept", "title": "Specific terms and topics:"}, {"id": "97733d0a-e5b7-40a5-b9c2-94cdb885e3e8", "type": "concept", "title": "ink slab"}, {"id": "80f12350-8b18-4417-ba4a-c06d13f87cc2", "type": "concept", "title": "brayer charge"}, {"id": "2d3b9365-07b6-4ce4-ac62-ce6b45651afe", "type": "concept", "title": "tack"}, {"id": "b26df99c-c4c9-4ca3-a126-15d69a5e9c77", "type": "concept", "title": "even roll-out"}, {"id": "4427d5b4-ce30-424b-b53c-ca0dea2fe543", "type": "concept", "title": "baren"}, {"id": "9eb6f7f7-9fcc-4cd6-ba7f-bfacf8ab124c", "type": "concept", "title": "spoon printing"}, {"id": "6d7e47a0-15b3-437a-9d87-ea44c8b5bdcd", "type": "concept", "title": "press blanket"}, {"id": "0d3916b9-4cb5-4c79-852a-1a0f27e9cc4c", "type": "concept", "title": "kiss impression"}, {"id": "380c2c09-5471-4b4d-8d98-5b6951f83fa2", "type": "concept", "title": "emboss"}, {"id": "4c856994-9841-433e-b06a-c3fa6416d9f0", "type": "concept", "title": "under-inking"}], "description": "The point is to control ink film, pressure, paper contact, and impression quality."}, {"id": "90617a92-29d6-48af-9cc9-90fdde4a9184", "type": "subtopic", "title": "Reduction and multi-block relief", "children": [{"id": "6b9becde-a3a9-45ff-9775-f0bd7bde3125", "type": "concept", "title": "Specific terms and topics:"}, {"id": "a9e3cb11-cac3-47ea-8eb3-3f6f3d1ed4d0", "type": "concept", "title": "reduction print"}, {"id": "0de04305-9c08-4206-8c24-d198893604cc", "type": "concept", "title